on" minlength="10" maxlength="1000"></textarea></label><label><input type="checkbox" required name="confirm_local_reversal" value="1">Conferi a reversão LOCAL integral apenas deste novo recebimento manual.</label><button type="submit">Registrar reversão local do novo manual</button><?= form_close(); }}elseif(in_array($detail['status'],[1,4],true)){echo form_open($url);$hidden('review'); ?><button type="submit">Consultar novamente e revisar</button><?= form_close(); ?>
